import{_ as a,o as i,c as s,a5 as n}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Contribuir con cambios acotados","description":"","frontmatter":{"title":"Contribuir con cambios acotados","docId":"developer.contributing","translationKey":"developer.contributing","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2e0522178ebee69ea5eb20fec3c0ec586f13950c51d658cb3a21843536b2f9f9","translationRevision":"101d8387f6ca3a6452434775ed0a609eb7bc68615a8ccd73c121df74e300fc0c","order":230},"headers":[],"relativePath":"es/developer/contributing.md","filePath":"es/developer/contributing.md","lastUpdated":1794611623000}'),t={name:"es/developer/contributing.md"};function o(r,e,c,l,d,p){return i(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="contributing-focused-changes" tabindex="-1">Contribuir con cambios acotados <a class="header-anchor" href="#contributing-focused-changes" aria-label="Permalink to &quot;Contribuir con cambios acotados {#contributing-focused-changes}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Prepara un cambio que otra persona pueda revisar y verificar. Lee <a href="https://github.com/nglmercer/TikTools-app/blob/remake/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>, los <code>AGENTS.md</code> aplicables y <a href="./setup.html">preparación</a> antes de editar. Usa Bun 1.4.4, Rust 1.95 o posterior cuando corresponda, archivos de bloqueo existentes y una rama basada en el destino previsto.</p><h2 id="define-and-implement-the-change" tabindex="-1">Definir e implementar el cambio <a class="header-anchor" href="#define-and-implement-the-change" aria-label="Permalink to &quot;Definir e implementar el cambio {#define-and-implement-the-change}&quot;">​</a></h2><ol><li>Inspecciona <code>git status</code> y conserva el trabajo ajeno. Excluye recursos generados, credenciales y bases locales del parche.</li><li>Sigue al propietario actual: núcleo Rust para servicios, módulos Control API para contratos, cliente tipado para cobertura SDK y <a href="./frontend.html">capas frontend</a> para presentación.</li><li>Ante cambios de contrato, modifica su definición canónica y regenera derivados juntos. No mantengas otra tabla completa manual de RPC o eventos.</li><li>Conserva las implementaciones particulares en paquetes externos de plugins; el host genérico descubre manifiestos en lugar de importar un plugin por nombre.</li><li>Explica el disparador concreto y el comportamiento resultante, incluidas rutas incompletas o experimentales.</li></ol><h2 id="validate-proportionately" tabindex="-1">Validar según el alcance <a class="header-anchor" href="#validate-proportionately" aria-label="Permalink to &quot;Validar según el alcance {#validate-proportionately}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>Los cambios nativos también requieren formato, lint, pruebas Rust y puertas CI aplicables. Un cambio exclusivamente documental debe comprobar contenido, órdenes y enlaces, sin declarar aceptación del runtime nativo. El ejecutor del proyecto posee las entradas admitidas; usa el acceso Cargo para banderas específicas de destinos nativos.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>La revisión contiene cambios concretos, evidencia útil y límites honestos. La política dirige solicitudes de cambio a <code>remake</code>; las etiquetas de versión las controla mantenimiento. Las instrucciones de contribución están disponibles, pero protección de ramas y comprobaciones remotas son responsabilidad administrativa, no garantías de una página Markdown.</p><h2 id="recover" tabindex="-1">Recuperación <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;Recuperación {#recover}&quot;">​</a></h2><p>Si falla la validación por una dependencia o biblioteca de plataforma ausente, identifica y repara el entorno sin debilitar la comprobación. Si divergen archivos generados, regenera desde su propietario y revisa las diferencias. Nunca publiques cookies, claves, credenciales ni capturas sin sanear. Cuando código y diseño heredado discrepen, explica la diferencia y usa la implementación actual para orientación pública. No sobrescribas archivos pendientes de otra persona para aparentar coherencia en una limpieza general.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Los sellos tienen significados separados: <code>sourceRevision</code> resume cuerpo inglés actual y <code>translationRevision</code> el cuerpo localizado de este artículo (sin frontmatter, sin blancos externos). Tras revisar fuente y traducciones usa <code>bun docs/scripts/record-review.ts developer/example.md</code>. Un cambio posterior invalida el sello correspondiente. Detecta cambios, no identidad humana ni equivalencia semántica: compara comandos, IDs RPC/entorno, claves payload, límites, activación/recuperación y negaciones. Traduce prosa completa conservando instrucciones técnicas.</p><p>Para migración dividida registra tema/encabezado original y destino concreto en mapa; usa fragmento si apunta a sección. El checker valida archivos/fragmentos y bytes históricos, pero revisión editorial verifica cobertura temática. No edites originales/provenance históricos para aprobar.</p>`,15)])])}const m=a(t,[["render",o]]);export{h as __pageData,m as default};
